XAML 数据绑定是 WPF、MAUI、Avalonia 等框架的核心特性，它实现了 UI 和数据的自动同步。
## 绑定模式

**OneWay**：数据源 → 目标（默认）
```xml
<TextBlock Text="{Binding UserName, Mode=OneWay}" />
```

**TwoWay**：数据源 ↔ 目标
```xml
<TextBox Text="{Binding UserName, Mode=TwoWay}" />
```

**OneTime**：只绑定一次
```xml
<TextBlock Text="{Binding Title, Mode=OneTime}" />
```

**OneWayToSource**：目标 → 数据源
```xml
<TextBox Text="{Binding SearchText, Mode=OneWayToSource}" />
```

## 绑定语法

**基本绑定**：
```xml
<TextBlock Text="{Binding UserName}" />
```

**指定数据源**：
```xml
<TextBlock Text="{Binding Source={StaticResource MyData}, Path=Name}" />
```

**相对绑定**：
```xml
<TextBlock Text="{Binding RelativeSource={RelativeSource Self}, Path=Name}" />
<TextBlock Text="{Binding RelativeSource={RelativeSource AncestorType=Window}, Path=Title}" />
```

**集合绑定**：
```xml
<ListBox ItemsSource="{Binding Users}" SelectedItem="{Binding SelectedUser}">
    <ListBox.ItemTemplate>
        <DataTemplate>
            <TextBlock Text="{Binding Name}" />
        </DataTemplate>
    </ListBox.ItemTemplate>
</ListBox>
```

## INotifyPropertyChanged

实现属性变化通知：
```csharp
public class ViewModel : INotifyPropertyChanged
{
    private string _userName;

    public string UserName
    {
        get => _userName;
        set
        {
            if (_userName != value)
            {
                _userName = value;
                OnPropertyChanged();
            }
        }
    }

    public event PropertyChangedEventHandler PropertyChanged;

    protected virtual void OnPropertyChanged([CallerMemberName] string propertyName = null)
    {
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
    }
}
```

**使用 CommunityToolkit.Mvvm**：
```csharp
public partial class ViewModel : ObservableObject
{
    [ObservableProperty]
    private string _userName;
}
```

## 值转换器

实现 IValueConverter 接口：
```csharp
public class BoolToVisibilityConverter : IValueConverter
{
    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
    {
        return (bool)value ? Visibility.Visible : Visibility.Collapsed;
    }

    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
    {
        return (Visibility)value == Visibility.Visible;
    }
}

public class StringToColorConverter : IValueConverter
{
    public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
    {
        var status = value as string;
        return status switch
        {
            "Active" => Colors.Green,
            "Inactive" => Colors.Gray,
            "Error" => Colors.Red,
            _ => Colors.Black
        };
    }

    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
    {
        throw new NotImplementedException();
    }
}
```

**使用转换器**：
```xml
<Window.Resources>
    <local:BoolToVisibilityConverter x:Key="BoolToVisibility" />
    <local:StringToColorConverter x:Key="StringToColor" />
</Window.Resources>

<TextBlock Visibility="{Binding IsVisible, Converter={StaticResource BoolToVisibility}}" />
<TextBlock Foreground="{Binding Status, Converter={StaticResource StringToColor}}" />
```

## 多绑定

```csharp
public class StringConcatConverter : IMultiValueConverter
{
    public object Convert(object[] values, Type targetType, object parameter, CultureInfo culture)
    {
        return string.Join(" ", values.Where(v => v != null));
    }

    public object[] ConvertBack(object value, Type[] targetTypes, object parameter, CultureInfo culture)
    {
        throw new NotImplementedException();
    }
}
```

```xml
<TextBlock>
    <TextBlock.Text>
        <MultiBinding Converter="{StaticResource StringConcat}">
            <Binding Path="FirstName" />
            <Binding Path="LastName" />
        </MultiBinding>
    </TextBlock.Text>
</TextBlock>
```

## 数据验证

**实现 INotifyDataErrorInfo**：
```csharp
public class ValidatableViewModel : ObservableObject, INotifyDataErrorInfo
{
    private readonly Dictionary<string, List<string>> _errors = new();

    public bool HasErrors => _errors.Any();

    public event EventHandler<DataErrorsChangedEventArgs> ErrorsChanged;

    public IEnumerable GetErrors(string propertyName)
    {
        return _errors.ContainsKey(propertyName) ? _errors[propertyName] : null;
    }

    private void ValidateProperty(string propertyName, object value)
    {
        var errors = new List<string>();

        if (propertyName == "UserName" && string.IsNullOrWhiteSpace(value as string))
        {
            errors.Add("用户名不能为空");
        }

        if (errors.Any())
            _errors[propertyName] = errors;
        else
            _errors.Remove(propertyName);

        ErrorsChanged?.Invoke(this, new DataErrorsChangedEventArgs(propertyName));
    }
}
```

```xml
<TextBox Text="{Binding UserName, Mode=TwoWay, ValidatesOnNotifyDataErrors=True}" />
```

