## 异步绑定

```csharp
public class ViewModel : ObservableObject
{
    private AsyncRelayCommand _loadCommand;

    public IAsyncRelayCommand LoadCommand => _loadCommand ??= new AsyncRelayCommand(LoadAsync);

    private async Task LoadAsync()
    {
        var data = await GetDataAsync();
        // 更新属性
    }
}
```

```xml
<Button Content="加载" Command="{Binding LoadCommand}" />
<ProgressBar IsIndeterminate="{Binding LoadCommand.IsRunning}" />
```

## 设计时数据

```xml
<Window d:DataContext="{d:DesignInstance Type=local:ViewModel, IsDesignTimeCreatable=True}">
    <TextBlock Text="{Binding Title}" />
</Window>
```

## 绑定性能优化

1. **使用 OneTime 绑定**：不需要更新的数据
2. **避免复杂绑定路径**：减少属性访问层级
3. **使用 x:Bind（UWP/WinUI）**：编译时绑定
4. **虚拟化集合**：大数据集使用虚拟化
5. **延迟绑定**：使用 Delay 属性

using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.ComponentModel;
using System.Globalization;
using System.Linq;
using System.Runtime.CompilerServices;
using System.Windows;
using System.Windows.Data;

namespace XAMLDataBindingDemo
{
    // Model
    public class User
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Email { get; set; }
        public DateTime BirthDate { get; set; }
        public bool IsActive { get; set; }
    }

    // ViewModel
    public class MainViewModel : INotifyPropertyChanged
    {
        private string _searchText;
        private User _selectedUser;
        private string _statusMessage;
        private bool _isBusy;

        public MainViewModel()
        {
            Users = new ObservableCollection<User>();
            LoadData();
        }

        public ObservableCollection<User> Users { get; }

        public string SearchText
        {
            get => _searchText;
            set
            {
                if (SetProperty(ref _searchText, value))
                {
                    FilterUsers();
                }
            }
        }

        public User SelectedUser
        {
            get => _selectedUser;
            set => SetProperty(ref _selectedUser, value);
        }

        public string StatusMessage
        {
            get => _statusMessage;
            set => SetProperty(ref _statusMessage, value);
        }

        public bool IsBusy
        {
            get => _isBusy;
            set => SetProperty(ref _isBusy, value);
        }

        public ICollectionView UsersView
        {
            get
            {
                var view = CollectionViewSource.GetDefaultView(Users);
                view.Filter = user =>
                {
                    if (string.IsNullOrWhiteSpace(SearchText))
                        return true;

                    var u = user as User;
                    return u.Name.Contains(SearchText, StringComparison.OrdinalIgnoreCase) ||
                           u.Email.Contains(SearchText, StringComparison.OrdinalIgnoreCase);
                };
                return view;
            }
        }

        private void LoadData()
        {
            Users.Add(new User { Id = 1, Name = "Alice", Email = "alice@example.com", BirthDate = new DateTime(1990, 1, 1), IsActive = true });
            Users.Add(new User { Id = 2, Name = "Bob", Email = "bob@example.com", BirthDate = new DateTime(1985, 5, 15), IsActive = true });
            Users.Add(new User { Id = 3, Name = "Charlie", Email = "charlie@example.com", BirthDate = new DateTime(1992, 8, 20), IsActive = false });

            StatusMessage = $"已加载 {Users.Count} 个用户";
        }

        private void FilterUsers()
        {
            UsersView.Refresh();
        }

        public event PropertyChangedEventHandler PropertyChanged;

        protected virtual void OnPropertyChanged([CallerMemberName] string propertyName = null)
        {
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
        }

        protected bool SetProperty<T>(ref T field, T value, [CallerMemberName] string propertyName = null)
        {
            if (EqualityComparer<T>.Default.Equals(field, value))
                return false;

            field = value;
            OnPropertyChanged(propertyName);
            return true;
        }
    }

    // 值转换器
    public class BoolToVisibilityConverter : IValueConverter
    {
        public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
        {
            return (bool)value ? Visibility.Visible : Visibility.Collapsed;
        }

        public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
        {
            return (Visibility)value == Visibility.Visible;
        }
    }

    public class DateTimeToStringConverter : IValueConverter
    {
        public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (value is DateTime date)
            {
                var format = parameter as string ?? "yyyy-MM-dd";
                return date.ToString(format);
            }
            return string.Empty;
        }

        public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (DateTime.TryParse(value as string, out var date))
                return date;
            return DependencyProperty.UnsetValue;
        }
    }

    public class AgeConverter : IValueConverter
    {
        public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (value is DateTime birthDate)
            {
                var age = DateTime.Today.Year - birthDate.Year;
                if (birthDate > DateTime.Today.AddYears(-age))
                    age--;
                return age;
            }
            return 0;
        }

        public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
        {
            throw new NotImplementedException();
        }
    }

    public class StatusToColorConverter : IValueConverter
    {
        public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (value is bool isActive)
            {
                return isActive ? "Green" : "Gray";
            }
            return "Black";
        }

        public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
        {
            throw new NotImplementedException();
        }
    }

    // 多绑定转换器
    public class FullNameConverter : IMultiValueConverter
    {
        public object Convert(object[] values, Type targetType, object parameter, CultureInfo culture)
        {
            if (values.Length >= 2 && values[0] is string first && values[1] is string last)
            {
                return $"{last} {first}";
            }
            return string.Empty;
        }

        public object[] ConvertBack(object value, Type[] targetTypes, object parameter, CultureInfo culture)
        {
            throw new NotImplementedException();
        }
    }

    // 数据验证
    public class ValidatableViewModel : INotifyPropertyChanged, INotifyDataErrorInfo
    {
        private string _email;
        private readonly Dictionary<string, List<string>> _errors = new();

        public string Email
        {
            get => _email;
            set
            {
                if (_email != value)
                {
                    _email = value;
                    ValidateEmail();
                    OnPropertyChanged();
                }
            }
        }

        public bool HasErrors => _errors.Any();

        public event EventHandler<DataErrorsChangedEventArgs> ErrorsChanged;
        public event PropertyChangedEventHandler PropertyChanged;

        public IEnumerable GetErrors(string propertyName)
        {
            return _errors.ContainsKey(propertyName) ? _errors[propertyName] : null;
        }

        private void ValidateEmail()
        {
            var errors = new List<string>();

            if (string.IsNullOrWhiteSpace(Email))
                errors.Add("邮箱不能为空");
            else if (!Email.Contains("@"))
                errors.Add("邮箱格式不正确");

            if (errors.Any())
                _errors[nameof(Email)] = errors;
            else
                _errors.Remove(nameof(Email));

            ErrorsChanged?.Invoke(this, new DataErrorsChangedEventArgs(nameof(Email)));
        }

        protected virtual void OnPropertyChanged([CallerMemberName] string propertyName = null)
        {
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
        }
    }
}
